import ast
import io

import pytest

from compiler_skel import Compiler
from x86_interp import interp_x86


# Each row is: test name, source program, simulated stdin, expected output.
CASES: list[tuple[str, str, str, list[int]]] = [
    ("constant", "x = 42\nprint(x)", "", [42]),
    ("zero", "x = 0\nprint(x)", "", [0]),
    ("print_literal", "print(7)", "", [7]),
    ("copy", "x = 9\ny = x\nprint(y)", "", [9]),
    ("copy_is_independent", "x = 9\ny = x\nx = 3\nprint(y)\nprint(x)", "", [9, 3]),
    ("reassignment", "x = 1\nx = 8\nprint(x)", "", [8]),
    ("negation", "x = 9\ny = -x\nprint(y)\nprint(x)", "", [-9, 9]),
    ("negate_literal", "x = -5\nprint(x)", "", [-5]),
    ("negate_in_place", "x = 9\nx = -x\nprint(x)", "", [-9]),
    ("add_constants", "x = 20 + 22\nprint(x)", "", [42]),
    ("add_variables", "x = 20\ny = 22\nz = x + y\nprint(z)", "", [42]),
    ("add_alias_left", "x = 40\nx = x + 2\nprint(x)", "", [42]),
    ("add_alias_right", "x = 40\nx = 2 + x\nprint(x)", "", [42]),
    ("add_alias_both", "x = 21\nx = x + x\nprint(x)", "", [42]),
    ("add_negative", "x = -5\ny = x + 2\nprint(y)", "", [-3]),
    ("combined", "x = 40\ny = x + 2\nz = -y\nprint(z)", "", [-42]),
    ("print_twice", "x = 7\nprint(x)\nprint(x)", "", [7, 7]),
    ("input", "x = input_int()\nprint(x)", "17\n", [17]),
    ("input_negative", "x = input_int()\nprint(x)", "-17\n", [-17]),
    ("input_then_add", "x = input_int()\ny = x + 2\nprint(y)", "40\n", [42]),
    ("two_inputs", "x = input_int()\ny = input_int()\nz = x + y\nprint(z)", "10\n32\n", [42]),
    ("print_then_input", "x = 7\nprint(x)\ny = input_int()\nprint(y)", "12\n", [7, 12]),
]


@pytest.mark.parametrize(
    "name,source,inputs,expected", CASES, ids=[case[0] for case in CASES]
)
def test_select_instructions(
    name: str, source: str, inputs: str, expected: list[int]
) -> None:
    program = Compiler().select_instructions(ast.parse(source))
    stdout = io.StringIO()

    try:
        actual = interp_x86(
            program,
            stdin=io.StringIO(inputs),
            stdout=stdout,
            max_steps=10_000,
        )
    except Exception as exc:
        pytest.fail(
            f"{name}: {type(exc).__name__}: {exc}\n"
            f"Source:\n{source}\n\nGenerated instructions:\n{program}"
        )

    assert actual == expected, (
        f"Source:\n{source}\n\nGenerated instructions:\n{program}"
    )
    assert stdout.getvalue() == "".join(f"{n}\n" for n in expected)
